Translate("frFR", "silverpine-forest", {
	title = "Forêt des Pins argentés",
	aliases = { "Pins argentés" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Forêt des Pins argentés s'étend vers le sud depuis les clairières de {link:tirisfal-glades}Tirisfal{/link} jusqu'au grand mur de {link:gilneas}Gilneas{/link}. De sombres pins se pressent sur ses collines, et à l'est ses rives plongent dans les eaux grises du {red:lordamere-lake}lac Lordamere{/red}. Ce fut jadis un pays paisible de fermes, de vergers et de moulins. C'est aujourd'hui une terre de morts et de maudits. Les {link:forsaken}Réprouvés{/link} tiennent ses routes depuis le {link:the-sepulcher}Sépulcre{/link}, le {link:scourge}Fléau{/link} tient une forteresse insulaire sur le lac, et dans les collines hurlent les hommes-loups d'un archimage fou de {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne rapporte l'année où les premiers humains s'établirent aux Pins argentés, ni quel seigneur les revendiqua le premier. Ses habitants cultivaient les vallées, soignaient les vergers et faisaient tourner les moulins. Au-dessus du hameau de {link:pyrewood-village}Bois-du-Bûcher{/link} se dressait le donjon du noble baron {link:baron-silverlaine}Silverlaine{/link}. Quand le roi {link:genn-greymane}Genn Greymane{/link} scella son royaume après la {link:second-war}Deuxième Guerre{/link}, le {link:the-greymane-wall}mur de Greymane{/link} s'éleva à travers le sud de la forêt, et les portes de {link:gilneas}Gilneas{/link} se refermèrent derrière lui. Les gens des Pins argentés restèrent du côté nord.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[La Dame noire a confié à son lieutenant {link:varimathras}Varimathras{/link} la tâche de prendre les terres du sud, et les Pins argentés en sont la première étape. Le grand exécuteur {link:high-executor-hadrec}Hadrec{/link} commande les {link:forsaken}Réprouvés{/link} au {link:the-sepulcher}Sépulcre{/link}, mais ses ennemis sont nombreux. Des gnolls Poils-putrides, relevés et asservis par le mage traître {link:thule-ravenclaw}Thule Ravenclaw{/link}, emportent des cadavres de {link:tirisfal-glades}Tirisfal{/link} jusqu'à l'île de Fenris. Les worgens de l'archimage {link:archmage-arugal}Arugal{/link} chassent dans les bois, et les villageois de {link:pyrewood-village}Bois-du-Bûcher{/link} se changent en bêtes chaque nuit. À {link:ambermill}Moulin-de-l'Ambre{/link}, les {link:the-wizards-of-ambermill}sorciers de Dalaran{/link} travaillent à un secret qui leur est propre et gardent les routes d'une main lourde. Au {link:the-greymane-wall}mur de Greymane{/link}, des réfugiés humains apeurés s'amassent devant des portes qui ne s'ouvriront pas.

En ces jours, les paladins de la {link:tyr-s-watch}Tyr's Watch{/link} ont envoyé un agent au Sépulcre, et une voyageuse des {link:skyborne}Skyborne{/link} est venue dans la forêt, apportant le deuil avec elle.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les {link:forsaken}Réprouvés{/link}.{/b} Gardes de la Mort, Traqueurs noirs, apothicaires et un archimage mort de {link:dalaran}Dalaran{/link}, tous au service de {link:sylvanas-windrunner}la Dame noire{/link} depuis le {link:the-sepulcher}Sépulcre{/link}.
• {b}Le {link:scourge}Fléau{/link}.{/b} Les gnolls Poils-putrides, les serviteurs de {link:thule-ravenclaw}Thule Ravenclaw{/link} et les morts sans esprit des anciennes fermes.
• {b}Les worgens.{/b} Les Moonrage et les Fils d'{link:archmage-arugal}Arugal{/link}, des hommes-loups sauvages qui obéissent, en partie, à l'archimage du {link:shadowfang-keep}Donjon d'Ombrecroc{/link}.
• {b}Les {link:pyrewood-villagers}maudits de Bois-du-Bûcher{/link}.{/b} Des villageois humains le jour et bêtes la nuit.
• {b}{link:the-wizards-of-ambermill}Les sorciers de Moulin-de-l'Ambre{/link}.{/b} Des mages du {link:kirin-tor}Kirin Tor{/link} et leurs gardes, amis ni des vivants ni des morts du nord.
• {b}Bêtes et murlocs.{/b} Worgs, ours grisonnants, grandes araignées et {link:murlocs}murlocs{/link} Vile Fin des rives du lac.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La peste.{/b} Pendant la {link:third-war}Troisième Guerre{/link}, la peste balaya {link:lordaeron}Lordaeron{/link}. Les fermiers du nord des Pins argentés moururent sur leurs terres et se relevèrent parmi le {link:scourge}Fléau{/link}.
• {b}Les worgens.{/b} Les {link:the-wizards-of-ambermill}sorciers de Dalaran{/link} combattirent le Fléau dans la forêt, et leurs propres morts se dressèrent contre eux. Contre l'avis de ses pairs, l'archimage {link:archmage-arugal}Arugal{/link} fit appel à des puissances d'au-delà du monde, et les worgens vinrent. Ils massacrèrent les morts, puis se retournèrent contre les sorciers. Ils prirent le donjon du baron {link:baron-silverlaine}Silverlaine{/link}, et Arugal en fit le sien.
• {b}Les {link:forsaken}Réprouvés{/link}.{/b} Avec le temps, les Réprouvés descendirent de {link:tirisfal-glades}Tirisfal{/link} vers le sud et firent du {link:the-sepulcher}Sépulcre{/link} leur place forte dans la forêt.]=],
		},
		{
			title = "Savoir de la forêt",
			text = [=[• Les apothicaires disent qu'il y a des âges, une peste tua toute créature vivante dans les eaux du lac Lordamere.
• Trois jeunes mages tissèrent jadis une seule baguette à partir de leurs baguettes d'apprenti, en signe d'amitié. L'un d'eux était {link:thule-ravenclaw}Thule Ravenclaw{/link}.
• Un archimage mort au {link:the-sepulcher}Sépulcre{/link} affirme qu'{link:archmage-arugal}Arugal{/link} n'a jamais eu le pouvoir de créer le moindre worgen.]=],
		},
	},
})

Translate("frFR", "the-sepulcher", {
	title = "Le Sépulcre",
	aliases = { "Sépulcre", "Sépulcre des Pins argentés" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Sépulcre est la place forte des {link:forsaken}Réprouvés{/link} aux {link:silverpine-forest}Pins argentés{/link}. Il se dresse sur une colline boisée au cœur de la forêt, un ancien lieu de sépulture où les morts veillent désormais sur le monde des vivants. D'ici, le grand exécuteur {link:high-executor-hadrec}Hadrec{/link} envoie ses Traqueurs noirs, et les gardes de la Mort tiennent les routes. Un archimage mort étudie la malédiction des worgens, un prêtre des ombres recueille chaque bribe de nouvelles, et un apothicaire de la Société travaille à la nouvelle peste. Des chauves-souris portent les cavaliers vers le nord jusqu'à {link:undercity}Undercity{/link}. En ces jours, le Sépulcre abrite aussi un envoyé de la {link:tyr-s-watch}Tyr's Watch{/link} et une jeune femme des {link:skyborne}Skyborne{/link}.]=],
		},
	},
})

Translate("frFR", "pyrewood-village", {
	title = "Bois-du-Bûcher",
	aliases = { "Bois-du-Bûcher" },
	sections = {
		{
			title = "Résumé",
			text = [=[Bois-du-Bûcher est un petit village du sud des {link:silverpine-forest}Pins argentés{/link}, sous les murs du {link:shadowfang-keep}Donjon d'Ombrecroc{/link}. De jour, il ressemble à n'importe quel hameau humain : un hôtel de ville, une auberge, des forgerons et des tailleurs à l'ouvrage, et des gardes dans les rues. Quand le soleil se couche, ses habitants deviennent des worgens. {link:archmage-arugal}Arugal{/link} les a tous chargés d'entraves enchantées, et il gouverne le village par son propre conseil, dont les membres sont ses marionnettes. Dans l'auberge se trouve le cabinet d'un apothicaire tombé sous la même malédiction. Une Traqueuse noire se cache dans l'hôtel de ville, attendant le retour du conseil.]=],
		},
	},
})

Translate("frFR", "ambermill", {
	title = "Moulin-de-l'Ambre",
	sections = {
		{
			title = "Résumé",
			text = [=[Moulin-de-l'Ambre est un village dans les collines du sud-est des {link:silverpine-forest}Pins argentés{/link}, près de la rive du lac Lordamere. Ce ne fut jamais un lieu important. Pourtant, les mages de {link:dalaran}Dalaran{/link} l'ont rempli de sorciers, d'invocateurs et de gardiens armés, et ils y expédient par chariot, depuis {link:hillsbrad-foothills}Hillsbrad{/link}, des caisses de cartes et de pendentifs runiques. Les {link:forsaken}Réprouvés{/link} croient savoir pourquoi. Moulin-de-l'Ambre repose sur un nœud d'énergie tellurique endormi, et un archimage s'emploie à le réveiller. Ce que le {link:kirin-tor}Kirin Tor{/link} compte faire d'une telle puissance, personne au {link:the-sepulcher}Sépulcre{/link} ne peut le dire.]=],
		},
	},
})

Translate("frFR", "fenris-isle", {
	title = "Ile de Fenris",
	sections = {
		{
			title = "Résumé",
			text = [=[L'île de Fenris se trouve sur le lac Lordamere, à l'est du {link:the-decrepit-ferry}bac délabré{/link}. C'est la place forte du {link:scourge}Fléau{/link} aux {link:silverpine-forest}Pins argentés{/link}. Les gnolls Poils-putrides grouillent sur ses rives et dans son donjon en ruine. Un bateau apporte les cadavres de {link:tirisfal-glades}Tirisfal{/link} de l'autre côté de l'eau depuis le bac, et sur l'île ces cadavres servent leur nouveau maître. Des murlocs Vile Fin chassent sur ses plages, et des bêtes du lac couvertes de mousse rampent parmi les roseaux. Depuis peu, les gardes de la Mort ont vu les gnolls jeter un grand corps sur un bûcher près de la rive. C'était le corps d'un {link:tauren}tauren{/link}.]=],
		},
	},
})

Translate("frFR", "fenris-keep", {
	title = "Donjon de Fenris",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Donjon de Fenris est la forteresse de l'île de Fenris. {link:thule-ravenclaw}Thule Ravenclaw{/link} y règne avec ses gnolls Poils-putrides. Dans sa cour, près de la vieille écurie, les gnolls ont enterré un corps sans tête dans une tombe anonyme. Ils ont gardé la tête comme jouet. Elle parle encore. Alaric, le premier serviteur de Thule, passa les meilleurs jours de sa vie dans ce donjon, et il en connaît les secrets, parmi lesquels une niche cachée dans la tour sud-ouest. Depuis peu, les gnolls gardent aussi un prisonnier vivant dans une cage à l'intérieur des murs.]=],
		},
	},
})

Translate("frFR", "the-decrepit-ferry", {
	title = "Le bac délabré",
	aliases = { "bac délabré" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le bac délabré est un vieil embarcadère sur la rive du lac Lordamere, à l'est du {link:the-sepulcher}Sépulcre{/link}. Il est pourri et presque oublié, mais il n'est pas à l'abandon. Des serviteurs de {link:thule-ravenclaw}Thule Ravenclaw{/link} le gardent, et des gnolls Poils-putrides vont et viennent. Dans le bateau qui y est amarré gisent des tas de corps emballés pour le voyage. De l'autre côté de l'eau, un second quai se dresse sur l'île de Fenris. Les {link:forsaken}Réprouvés{/link} ont appris que les corps viennent des fosses communes de {link:tirisfal-glades}Tirisfal{/link}, parmi eux une femme de {link:brill}Brill{/link} nommée Deliah, et qu'ils achèvent tous leur voyage sur l'île.]=],
		},
	},
})

Translate("frFR", "the-dead-field", {
	title = "Le Champ des morts",
	aliases = { "Champ des morts", "Champs des morts" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Champ des morts est une ferme abandonnée du nord des {link:silverpine-forest}Pins argentés{/link}. Les gnolls Poils-putrides en ont fait un camp, et les Traqueurs noirs qui le surveillaient pensaient que les gnolls se préparaient à la guerre. Les {link:forsaken}Réprouvés{/link} les frappèrent plus d'une fois, et chaque fois ils furent mis en déroute par une banshee nommée Nightlash, qui venait en aide aux gnolls par sa magie. {link:high-executor-hadrec}Hadrec{/link} voulait la voir détruite. On dit que lorsque Nightlash tombe, son essence se change en poussière.]=],
		},
	},
})

Translate("frFR", "the-ivar-patch", {
	title = "Le lopin d'Ivar",
	aliases = { "lopin d'Ivar" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le lopin d'Ivar était la ferme d'un homme nommé {link:ivar-the-foul}Ivar{/link}, à l'extrême nord des {link:silverpine-forest}Pins argentés{/link}. Quand la peste vint, Ivar, la plupart de sa famille et ses ouvriers tombèrent tous et se relevèrent parmi le {link:scourge}Fléau{/link}. Ivar hante encore sa grange sous la forme d'une goule. Les Traqueurs noirs {link:rane-yorick}Rane{/link} et {link:quinn-yorick}Quinn Yorick{/link} tombèrent ici dans une embuscade au cours de leur mission, et ils firent de sa vieille maison leur abri. De ses fenêtres, Rane monte la garde, tandis que Quinn se soigne à l'étage.]=],
		},
	},
})

Translate("frFR", "malden-s-orchard", {
	title = "Verger de Malden",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Verger de Malden se trouve à l'extrême nord-est des {link:silverpine-forest}Pins argentés{/link}, près de la frontière de {link:tirisfal-glades}Tirisfal{/link}. Ses arbres ne sont plus cueillis, et quiconque vivait dans sa chaumière est parti. Des worgs emplissent désormais le verger, si nombreux qu'un Traqueur noir envoyé en reconnaissance resta pris au piège dans la chaumière pendant des jours. Les worgs surveillaient la porte et attendaient qu'il sorte. Parmi eux chasse un grand worg noir connu sous le nom de Gorefang.]=],
		},
	},
})

Translate("frFR", "valgan-s-field", {
	title = "Champ de Valgan",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Champ de Valgan est une ferme à blé du nord des {link:silverpine-forest}Pins argentés{/link}, juste au nord d'un pont sur une petite rivière. Quand l'archimage {link:archmage-arugal}Arugal{/link} vint pour la première fois dans la forêt, c'est ici qu'il séjourna. Il laissa derrière lui des grimoires, et les Traqueurs noirs qui les trouvèrent ne purent les emporter. Parmi eux se trouvait un sort qu'Arugal appelait son remède. Des worgens rôdent désormais sur les terres autour de la ferme.]=],
		},
	},
})

Translate("frFR", "north-tide-s-hollow", {
	title = "Creux de la côte nord",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Creux de la côte nord est une étendue de bois juste au nord du {link:the-sepulcher}Sépulcre{/link}, en direction de la mer de l'ouest. Les worgens Moonrage en ont fait l'un de leurs repaires. Leurs gloutons et leurs âmes noires rôdent parmi les arbres, et chacun porte une entrave enchantée fabriquée par {link:archmage-arugal}Arugal{/link}. L'archimage mort du Sépulcre a étudié ces entraves de près. Elles furent la première preuve, dit-il, que la magie d'Arugal était plus faible que le monde ne le croyait.]=],
		},
	},
})

Translate("frFR", "olsen-s-farthing", {
	title = "Ferme des Olsen",
	sections = {
		{
			title = "Résumé",
			text = [=[La Ferme des Olsen est une ferme en ruine au bord de la grand-route, au sud du {link:the-sepulcher}Sépulcre{/link}. Elle commerçait autrefois avec chaque chariot qui traversait la forêt. La ferme est aujourd'hui envahie par les morts. Des pillards et des esclaves au service de {link:thule-ravenclaw}Thule Ravenclaw{/link} s'y sont rassemblés, et ils fondent sur quiconque s'approche. Les {link:forsaken}Réprouvés{/link} doivent passer devant eux chaque fois qu'ils prennent la route du sud.]=],
		},
	},
})

Translate("frFR", "the-skittering-dark", {
	title = "Le Grouillement",
	aliases = { "Grouillement" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Grouillement est un creux étouffé de toiles au nord-ouest des {link:silverpine-forest}Pins argentés{/link}, près de la mer. De grandes araignées traqueuses des mousses et rampantes des brumes y nichent, et des ours rôdent à ses abords. Les apothicaires du {link:the-sepulcher}Sépulcre{/link} prisent le sang de ses araignées. Mêlé à une toxine tirée du cœur d'un ours grisonnant, il donne un élixir mortel, et la Société espère que ce sera un pas vers la nouvelle peste. Un pêcheur réprouvé lance sa ligne depuis la rive voisine, comme si les araignées ne le concernaient pas.]=],
		},
	},
})

Translate("frFR", "deep-elem-mine", {
	title = "Mine du gouffre d'Elem",
	sections = {
		{
			title = "Résumé",
			text = [=[La Mine du gouffre d'Elem se trouve dans les collines du centre des {link:silverpine-forest}Pins argentés{/link}, au sud-est du {link:the-sepulcher}Sépulcre{/link}. La magie d'{link:archmage-arugal}Arugal{/link} s'étendit jusqu'ici, et le contremaître même de la mine, {link:grimson-the-pale}Grimson the Pale{/link}, en fut victime. Les worgens Moonrage tiennent désormais les galeries. Les {link:forsaken}Réprouvés{/link} veulent la mine pour la guerre à venir, car son minerai nourrirait l'avancée de {link:varimathras}Varimathras{/link} vers le sud. {link:dalar-dawnweaver}Dalar Dawnweaver{/link} croit qu'une fois le contremaître mort, la mine appartiendra à {link:sylvanas-windrunner}la Dame noire{/link}.]=],
		},
	},
})

Translate("frFR", "beren-s-peril", {
	title = "Péril de Beren",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Péril de Beren est une grotte dans les collines au sud-ouest de {link:ambermill}Moulin-de-l'Ambre{/link}, non loin d'un camp des {link:the-wizards-of-ambermill}sorciers de Dalaran{/link}. Les {link:forsaken}Réprouvés{/link} apprirent de leurs éclaireurs qu'une bande de morts-vivants s'y était rassemblée. Des besogneux et des gardiens au service de {link:thule-ravenclaw}Thule Ravenclaw{/link} préparaient une attaque contre le {link:the-sepulcher}Sépulcre{/link} lui-même. Le prêtre des ombres {link:shadow-priest-allister}Allister{/link} n'attendit pas qu'ils se mettent en marche. Il envoya ses propres agents dans la grotte pour frapper le premier.]=],
		},
	},
})

Translate("frFR", "gates-of-shadowfang-keep", {
	title = "Portes du Donjon d'Ombrecroc",
	sections = {
		{
			title = "Résumé",
			text = [=[Le {link:shadowfang-keep}Donjon d'Ombrecroc{/link} s'élève sur une colline du sud des {link:silverpine-forest}Pins argentés{/link}, juste au nord de {link:pyrewood-village}Bois-du-Bûcher{/link}. Ce fut le donjon du baron {link:baron-silverlaine}Silverlaine{/link}, jusqu'à ce que les worgens le prennent et que l'archimage {link:archmage-arugal}Arugal{/link} en fasse sa demeure. Depuis la route, le donjon ne montre que ses murs sombres. Les Fils d'Arugal parcourent la forêt à partir d'ici, de grands worgens qui servent l'archimage comme ses enfants. Les {link:forsaken}Réprouvés{/link} ont envoyé des Traqueurs noirs à l'intérieur. Aucun n'est revenu.]=],
		},
	},
})

Translate("frFR", "the-greymane-wall", {
	title = "Le mur de Greymane",
	aliases = { "mur de Greymane" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le mur de Greymane court le long de la bordure sud des {link:silverpine-forest}Pins argentés{/link} et ferme le royaume de {link:gilneas}Gilneas{/link} au nord. Le {link:genn-greymane}roi Genn Greymane{/link} l'éleva après la {link:second-war}Deuxième Guerre{/link}, et ses portes sont restées closes depuis, même quand la peste vint. Devant le mur, des humains qui ont fui le nord ont formé un camp de désespérés. Beaucoup sont malades. Un forgeron aveugle travaille parmi eux. Des worgens et des worgs rôdent tout près, et les {link:forsaken}Réprouvés{/link} craignent que la malédiction ne passe aux réfugiés. Les Gilnéens ont clairement fait savoir que personne ne passerait.]=],
		},
	},
})

Translate("frFR", "pyrewood-villagers", {
	title = "Villageois de Bois-du-Bûcher",
	aliases = { "Conseil de Bois-du-Bûcher", "maudits de Bois-du-Bûcher" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les villageois de {link:pyrewood-village}Bois-du-Bûcher{/link} vivent deux vies. Le jour, ils sont humains : gardes, anciens, forgerons, tailleurs et travailleurs du cuir vaquant à leurs tâches. Quand le soleil se couche, la malédiction de l'archimage {link:archmage-arugal}Arugal{/link} les saisit, et ils deviennent des worgens Moonrage. Chacun d'eux porte une entrave enchantée qu'Arugal leur a imposée.]=],
		},
		{
			title = "Le conseil",
			text = [=[{link:pyrewood-village}Bois-du-Bûcher{/link} est toujours gouverné par son conseil, huit conseillers sous l'autorité du seigneur maire Morrison. Les {link:forsaken}Réprouvés{/link} croient que le conseil n'est plus son propre maître. {link:archmage-arugal}Arugal{/link} se sert d'eux comme de marionnettes pour garder obéissantes les bêtes du village pendant que son attention se porte sur le {link:shadowfang-keep}Donjon d'Ombrecroc{/link}. La {link:deathstalker-faerleia}Traqueuse noire Faerleia{/link} espérait qu'une fois le conseil mort, les worgens se retourneraient contre Arugal lui-même.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne rapporte si les villageois se souviennent le jour de ce qu'ils font la nuit. Il n'est pas écrit quand la malédiction s'abattit sur eux pour la première fois.]=],
		},
	},
})

Translate("frFR", "the-wizards-of-ambermill", {
	title = "Les sorciers de Moulin-de-l'Ambre",
	aliases = { "sorciers de Dalaran", "Kirin Tor de Moulin-de-l'Ambre" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les sorciers de Moulin-de-l'Ambre sont des mages de {link:dalaran}Dalaran{/link} et les serviteurs qui les gardent : apprentis, invocateurs, mages, guetteurs, gardiens et protecteurs, et même un maître brasseur et un mineur. Ils répondent au {link:kirin-tor}Kirin Tor{/link}, et ils ont fait d'un village endormi des {link:silverpine-forest}Pins argentés{/link} une forteresse à eux.]=],
		},
		{
			title = "Leur œuvre",
			text = [=[{link:ambermill}Moulin-de-l'Ambre{/link} repose sur un nœud d'énergie tellurique longtemps resté dormant. Le {link:kirin-tor}Kirin Tor{/link} l'a choisi pour cette raison, et son archimage {link:archmage-ataeric}Ataeric{/link} tisse le réveil de ses énergies en vue d'un grand dessein. Les pendentifs runiques qu'ils portent sont d'anciens outils du Kirin Tor, servant à canaliser une telle puissance. Les sorciers tiennent aussi un camp au nord de {link:pyrewood-village}Bois-du-Bûcher{/link}, où arrivent leurs caisses d'{link:hillsbrad-foothills}Hillsbrad{/link}.]=],
		},
		{
			title = "Entre les vivants et les morts",
			text = [=[Pour les {link:forsaken}Réprouvés{/link}, {link:ambermill}Moulin-de-l'Ambre{/link} est le cœur de la résistance humaine dans la forêt. Les sorciers montent la garde sur les routes depuis que la grande barrière de {link:dalaran}Dalaran{/link} est tombée, et ils ne laissent passer personne librement. Ce qu'ils craignent, ils ne le disent pas.]=],
		},
	},
})

Translate("frFR", "dalar-dawnweaver", {
	title = "Dalar Dawnweaver",
	subtitle = "Archimage des Réprouvés",
	found = "Le Sépulcre",
	hint = [=[Parlez à l'archimage mort qui étudie la malédiction d'Arugal au Sépulcre.]=],
	allegiance = "Réprouvés · autrefois le Kirin Tor",
	aliases = { "Dalar" },
	sections = {
		{
			title = "Résumé",
			text = [=[Dalar Dawnweaver fut de son vivant un archimage de {link:dalaran}Dalaran{/link}. Il avertit jadis le {link:kirin-tor}Kirin Tor{/link}, qui ne l'écouta pas. Aujourd'hui, il sert {link:sylvanas-windrunner}la Dame noire{/link} au {link:the-sepulcher}Sépulcre{/link}. Il affiche un mépris ouvert pour {link:archmage-arugal}Arugal{/link}. Il le traite de charlatan qui étayait des sorts faibles avec des babioles enchantées et qui n'aurait jamais dû parler au nom du Kirin Tor.]=],
		},
		{
			title = "Importance",
			text = [=[Dalar est l'érudit des {link:forsaken}Réprouvés{/link} pour la malédiction des worgens. Depuis peu, il est parvenu à une conclusion audacieuse : {link:archmage-arugal}Arugal{/link} pouvait asservir les bêtes, mais ne les a jamais créées, et la malédiction se propage par quelque autre voie.]=],
		},
	},
	chapters = {
		{
			title = "Une imposture dévoilée",
			hint = [=[Apportez à l'archimage mort des preuves venues du mur de Greymane.]=],
			text = [=[Dalar passa au crible les entraves, les grimoires et les restes des bêtes jusqu'à en être certain. La fameuse malédiction d'{link:archmage-arugal}Arugal{/link} était trop faible pour durer plus de quelques instants. Dalar rit, car il avait démasqué l'archimage comme un imposteur. Puis il en vit le prix : le remède ne valait rien lui non plus.]=],
		},
	},
	mentions = {
		{ text = "Faites vos preuves" },
		{ text = "La folie d'{link:archmage-arugal}Arugal{/link}, le remède" },
		{ text = "La folie d'{link:archmage-arugal}Arugal{/link}, les entraves" },
		{ text = "La folie d'{link:archmage-arugal}Arugal{/link}, la mine" },
		{
			text = [=[La folie d'{link:archmage-arugal}Arugal{/link}, {link:pyrewood-village}Bois-du-Bûcher{/link}]=],
		},
		{ text = "Enrayer la propagation" },
		{ text = "Les intentions de {link:dalaran}Dalaran{/link}" },
		{ text = "{link:archmage-arugal}Arugal{/link} doit mourir" },
	},
	bonds = {
		{ id = "archmage-arugal", name = "Archimage Arugal", note = "le fou qu'il méprise" },
		{ id = "shadow-priest-allister", name = "Prêtre des ombres Allister", note = "partage sa surveillance de Moulin-de-l'Ambre" },
	},
})

Translate("frFR", "high-executor-hadrec", {
	title = "Grand exécuteur Hadrec",
	subtitle = "Commandant du Sépulcre",
	found = "Le Sépulcre",
	hint = "Parlez au grand exécuteur qui commande le Sépulcre.",
	allegiance = "Réprouvés · Garde de la Mort",
	aliases = { "Hadrec" },
	sections = {
