			title = "Résumé",
			text = [=[Le grand exécuteur Hadrec commande les {link:forsaken}Réprouvés{/link} aux {link:silverpine-forest}Pins argentés{/link}. La forêt, dit-il, grouille d'ennemis, et son peuple doit les repousser ou périr. Il n'avait pas prévu combien de serviteurs du {link:scourge}Fléau{/link} l'y attendaient, ni combien la tâche de ses éclaireurs serait rude.]=],
		},
		{
			title = "Importance",
			text = [=[Hadrec transforme des rapports épars en une guerre. À partir d'un anneau perdu sur un bateau de cadavres, il remonta la piste des gnolls Poils-putrides jusqu'à l'île de Fenris et jusqu'à leur maître.]=],
		},
	},
	chapters = {
		{
			title = "L'assaut contre l'île de Fenris",
			hint = [=[Apportez à Hadrec la tête du maître du Fléau aux Pins argentés.]=],
			text = [=[Quand Hadrec eut appris tout ce qu'il pouvait, il ordonna de frapper l'île de Fenris. {link:thule-ravenclaw}Thule Ravenclaw{/link} tomba dans son propre donjon. L'énergie qui jaillit de sa mort se fit sentir jusqu'au {link:the-sepulcher}Sépulcre{/link}.]=],
		},
	},
	mentions = {
		{ text = "Traqueurs noirs disparus" },
		{ text = "Les {link:the-dead-field}Champs des morts{/link}" },
		{ text = "{link:the-decrepit-ferry}Le bac délabré{/link}" },
		{ text = "Indices sur les Poils-putrides" },
		{ text = "L'anneau gravé" },
		{ text = "Ichor de Poils-putrides" },
		{ text = "Des Traqueurs noirs à {link:shadowfang-keep}Ombrecroc{/link}" },
	},
	bonds = {
		{ id = "thule-ravenclaw", name = "Thule Ravenclaw", note = "son principal ennemi" },
		{ id = "rane-yorick", name = "Rane Yorick", note = "l'un de ses Traqueurs noirs" },
		{ id = "apothecary-renferrel", name = "Apothicaire Renferrel", note = "étudie les Poils-putrides pour lui" },
		{ id = "magistrate-sevren", name = "Magistrat Sevren", note = "tient les registres des morts" },
	},
})

Translate("frFR", "rane-yorick", {
	title = "Rane Yorick",
	subtitle = "Traqueur noir",
	found = "Le lopin d'Ivar",
	hint = [=[Cherchez le Traqueur noir qui monte la garde sur une vieille ferme de l'extrême nord.]=],
	allegiance = "Réprouvés · Traqueurs noirs",
	aliases = { "Rane" },
	sections = {
		{
			title = "Résumé",
			text = [=[Rane Yorick mena une petite mission de {red:deathstalkers}Traqueurs noirs{/red} dans le nord des {link:silverpine-forest}Pins argentés{/link} : lui-même, son frère {link:quinn-yorick}Quinn{/link} et {link:deathstalker-erland}Erland McKree{/link}. Leur tâche était d'évaluer la force de la faune et du {link:scourge}Fléau{/link}. La goule {link:ivar-the-foul}Ivar{/link} leur tendit une embuscade à sa ferme. Ils remportèrent le combat, mais Quinn fut grièvement blessé. Rane tint la vieille maison d'Ivar pendant qu'Erland poursuivait seul.]=],
		},
		{
			title = "Importance",
			text = [=[Le rapport de Rane donna au {link:the-sepulcher}Sépulcre{/link} sa première image claire du nord : des worgs en grand nombre, et des gnolls au {link:the-dead-field}Champ des morts{/link} qui semblaient prêts à la guerre.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il veille sur son frère blessé.
• Il rédige le rapport de mission, et demande que son porteur soit honoré.]=],
		},
	},
	mentions = {
		{ text = "{link:ivar-the-foul}Ivar l'Infect{/link}" },
		{ text = "Cœurs sauvages" },
		{ text = "Le rapport des Traqueurs noirs" },
	},
	bonds = {
		{ id = "quinn-yorick", name = "Quinn Yorick", note = "son frère" },
		{ id = "deathstalker-erland", name = "Traqueur noir Erland", note = "de la même mission" },
		{ id = "high-executor-hadrec", name = "Grand exécuteur Hadrec", note = "son commandant" },
	},
})

Translate("frFR", "quinn-yorick", {
