	hint = [=[Parlez au prêtre des ombres qui recueille les nouvelles au Sépulcre.]=],
	allegiance = "Réprouvés",
	aliases = { "Allister" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le prêtre des ombres Allister croit que l'information est l'arme la plus acérée des {link:forsaken}Réprouvés{/link}. Ses éclaireurs et ses agents surveillent chaque mouvement du {link:scourge}Fléau{/link} en {link:lordaeron}Lordaeron{/link}. Ses yeux sont aussi tournés vers {link:ambermill}Moulin-de-l'Ambre{/link}. Les sorciers de {link:dalaran}Dalaran{/link} s'intéressent au village, et pour Allister cela seul signifie qu'il cache quelque chose de valeur.]=],
		},
		{
			title = "Importance",
			text = [=[Allister découvrit l'œuvre du {link:kirin-tor}Kirin Tor{/link} à {link:ambermill}Moulin-de-l'Ambre{/link} et trouva l'archimage qui la dirigeait. Il apprit aussi le rassemblement de morts-vivants au {link:beren-s-peril}Péril de Beren{/link}, et les frappa avant qu'ils ne frappent le {link:the-sepulcher}Sépulcre{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il saisit une caisse de cartes et de pendentifs destinée à {link:ambermill}Moulin-de-l'Ambre{/link}.
• Il ordonna la mort de l'archimage qui tissait les énergies telluriques.
• Il écrivit un livre contre l'Église de la Lumière, qui a voyagé loin.]=],
		},
	},
	mentions = {
		{ text = "Passages de frontière" },
		{ text = "Enquêtes à {link:ambermill}Moulin-de-l'Ambre{/link}" },
		{ text = "Le tisseur" },
		{ text = "Le {link:beren-s-peril}Péril de Beren{/link}" },
		{ text = "Surveiller les routes" },
	},
	bonds = {
		{ id = "dalar-dawnweaver", name = "Dalar Dawnweaver", note = "déchiffre les secrets des sorciers" },
		{ id = "archmage-ataeric", name = "Archimage Ataeric", note = "le tisseur dont il voulait la mort" },
	},
})

Translate("frFR", "apothecary-renferrel", {
