Translate("frFR", "archmage-ataeric", {
	title = "Archimage Ataeric",
	subtitle = "Le tisseur de Moulin-de-l'Ambre",
	found = "Moulin-de-l'Ambre",
	hint = [=[Cherchez l'archimage qui tisse les énergies telluriques de Moulin-de-l'Ambre.]=],
	allegiance = "Kirin Tor",
	aliases = { "Ataeric" },
	sections = {
		{
			title = "Résumé",
			text = [=[Ataeric est un archimage du {link:kirin-tor}Kirin Tor{/link} et le maître de l'œuvre de {link:ambermill}Moulin-de-l'Ambre{/link}. Il dirige le réveil du nœud tellurique endormi sous le village. Des mages et des gardiens l'entourent, et son bâton est le foyer de son tissage. Son œuvre est déjà bien avancée.]=],
		},
		{
			title = "Importance",
			text = [=[Pour les {link:forsaken}Réprouvés{/link}, Ataeric est l'homme le plus dangereux de {link:ambermill}Moulin-de-l'Ambre{/link}. Si son tissage est achevé, ils craignent que le {link:kirin-tor}Kirin Tor{/link} ne dispose d'une source de grande puissance au cœur de la forêt.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne rapporte ce que le {link:kirin-tor}Kirin Tor{/link} compte faire de la puissance de {link:ambermill}Moulin-de-l'Ambre{/link}.]=],
		},
	},
	mentions = {
		{ text = "Enquêtes à {link:ambermill}Moulin-de-l'Ambre{/link}" },
		{ text = "Le tisseur" },
	},
	bonds = {
		{ id = "shadow-priest-allister", name = "Prêtre des ombres Allister", note = "ordonna sa mort" },
		{ id = "the-wizards-of-ambermill", name = "Les sorciers de Moulin-de-l'Ambre", note = "les siens" },
	},
})

Translate("frFR", "thule-ravenclaw", {
	title = "Thule Ravenclaw",
	subtitle = "Maître du Donjon de Fenris",
	found = "Donjon de Fenris",
	hint = [=[Affrontez le mage traître qui gouverne les Poils-putrides depuis le Donjon de Fenris.]=],
	allegiance = "Fléau",
	aliases = { "Thule" },
	sections = {
		{
			title = "Résumé",
			text = [=[Thule Ravenclaw était un jeune mage très prometteur avant la {link:third-war}Troisième Guerre{/link}. Avec {link:bethor-iceshard}Bethor Iceshard{/link} et {link:gunther-arcanus}Gunther Arcanus{/link}, il tissa une baguette à partir de leurs baguettes d'apprenti, en signe de leur amitié. Quand le roi-liche s'éleva, Thule les trahit et rejoignit le {link:scourge}Fléau{/link}. Aujourd'hui, il règne sur le {link:fenris-keep}Donjon de Fenris{/link}. Par la magie de démoniste et de nécromancie, il créa les {link:gnolls}gnolls{/link} Poils-putrides, et il les envoie contre les {link:forsaken}Réprouvés{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Thule est la principale puissance du {link:scourge}Fléau{/link} aux {link:silverpine-forest}Pins argentés{/link}. Il alla jusqu'à décapiter son propre serviteur Alaric, que sa magie avait lié à une non-vie sans fin.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il vola la Woven Wand et la cacha dans le {link:fenris-keep}Donjon de Fenris{/link}.]=],
		},
	},
	mentions = {
		{ text = "Thule Ravenclaw" },
		{ text = "Reposer en morceaux" },
		{ text = "Une baguette pour {link:bethor-iceshard}Bethor{/link}" },
		{ text = "Assaut sur l'île de Fenris" },
	},
	bonds = {
		{ id = "bethor-iceshard", name = "Bethor Iceshard", note = "son ami trahi" },
		{ id = "gunther-arcanus", name = "Gunther Arcanus", note = "son ami trahi" },
		{ id = "high-executor-hadrec", name = "Grand exécuteur Hadrec", note = "veut sa tête" },
	},
})

