Translate("frFR", "lumina-windsinger", {
	title = "Lumina Windsinger",
	subtitle = "Windshaper des Skyborne",
	found = "Le Sépulcre, après avoir été délivrée du Donjon de Fenris",
	hint = [=[Cherchez l'elfe touchée par le ciel qui s'abrite au Sépulcre.]=],
	allegiance = "Windshapers · invitée du Cercle terrestre",
	aliases = { "Lumina" },
	sections = {
		{
			title = "Résumé",
			text = [=[Lumina Windsinger est l'une des {link:skyborne}Skyborne{/link}, du peuple appelé les {link:windshapers}Windshapers{/link}. Elle vint en ces terres comme invitée du {link:earthen-ring}Cercle terrestre{/link}. Avec le {link:tauren}tauren{/link} Banon, elle traversa les {link:silverpine-forest}Pins argentés{/link} en direction des {link:arathi-highlands}Hautes-terres d'Arathi{/link}. En chemin, un worgen frappa. Banon se jeta devant elle et fut mordu. Puis les gnolls les trouvèrent. Lumina fut mise en cage dans le {link:fenris-keep}Donjon de Fenris{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Lumina vit la malédiction à l'œuvre. À la fin, Banon la reconnaissait et se dressa pourtant pour la frapper. Elle a juré sur le ciel de détruire le worgen qui le condamna.]=],
		},
	},
	chapters = {
		{
			title = "La dette",
			hint = "Écoutez le récit de Lumina au Sépulcre.",
			text = [=[La bête était Old Fire-Eye, le plus grand des worgens du sud, qui refusait de rester mort. Une lame d'argent lunaire fut forgée pour en finir avec lui.]=],
		},
	},
	mentions = {
		{ text = "Lumina Windsinger" },
		{ text = "La colère de la {link:windshapers}Windshaper{/link}" },
		{ text = "Old Fire-Eye" },
	},
	bonds = {
		{ id = "trevan-rol", name = "Trevan Rol", note = "la pista" },
	},
})

Translate("frFR", "tabitha-heartweaver", {
