})

Translate("frFR", "genn-greymane", {
	title = "Genn Greymane",
	subtitle = "Roi de Gilneas",
	found = "Derrière le mur de Greymane, en Gilneas",
	hint = "Découvrez le roi dont le mur ferme le sud des Pins argentés.",
	allegiance = "Royaume de Gilneas",
	aliases = { "Greymane", "roi Greymane", "roi Genn Greymane" },
	sections = {
		{
			title = "Résumé",
			text = [=[Genn Greymane est le roi de {link:gilneas}Gilneas{/link}. C'est un souverain fier et obstiné, un guerrier qui se fie à son propre peuple et à peu d'autres. C'est lui qui retira Gilneas de l'{link:alliance}Alliance{/link} après la {link:second-war}Deuxième Guerre{/link}, et lui qui éleva le grand mur à travers le sud des {link:silverpine-forest}Pins argentés{/link}. Derrière ce mur, son royaume a tenu son propre conseil à travers toute la ruine du nord.]=],
		},
		{
			title = "Importance",
			text = [=[Greymane est le seigneur qui choisit de rester seul. Son mur épargna à {link:gilneas}Gilneas{/link} le coût des guerres des autres nations. Il laissa aussi le nord affronter le {link:scourge}Fléau{/link} sans l'armée gilnéenne. Le mur a-t-il sauvé son royaume ou l'a-t-il seulement caché ? Nul au-dehors ne peut le dire.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Quand {link:stormwind-city}Stormwind{/link} tomba, il vint avec les autres souverains humains au conseil de {link:lordaeron}Lordaeron{/link} convoqué par le roi {link:terenas-menethil}Terenas{/link}. Il doutait du danger, et se vanta que l'armée de {link:gilneas}Gilneas{/link} pouvait affronter n'importe quelle menace.
• Il rejoignit l'{link:alliance}Alliance de Lordaeron{/link} à contrecœur, et lui donna bien moins que son royaume n'aurait pu donner.
• Après la guerre, il se querella avec ses pairs au sujet du coût des camps d'internement des orcs et de {link:nethergarde-keep}Rempart-du-Néant{/link}. Quand il se plaignit des dépenses de la forteresse, le jeune roi {link:varian-wrynn}Varian Wrynn{/link} répondit qu'aucun prix ne pouvait être mis sur leur sécurité.
• Il chercha à peser sur le sort de l'{link:alterac-mountains}Alterac{/link} privé de chef, et soutint un prétendant à son trône.
• Il retira Gilneas de l'Alliance, bâtit le {link:the-greymane-wall}mur de Greymane{/link} et en ferma les portes.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune nouvelle n'est sortie de {link:gilneas}Gilneas{/link} depuis que ses portes ont été fermées. Ce que le roi Greymane sait des worgens à sa porte, et ce qui se passe dans son royaume, aucune chronique de ces jours ne peut le dire.]=],
		},
	},
	chapters = {
		{
			title = "Le mur qui porte son nom",
			hint = "Tenez-vous devant le mur qui porte le nom du roi.",
			text = [=[Greymane croyait que {link:gilneas}Gilneas{/link} ne devait rien aux guerres des autres royaumes. Quand l'{link:alliance}Alliance{/link} demanda à son peuple de payer pour les camps de prisonniers orcs, il refusa, et il retira entièrement son royaume de l'Alliance. Puis il l'emmura. {link:the-greymane-wall}Le mur de Greymane{/link} s'éleva le long de la frontière nord de Gilneas. Quand la peste vint en {link:lordaeron}Lordaeron{/link}, ses portes restèrent closes. Aucune armée gilnéenne ne marcha vers le nord pour aider le royaume mourant.]=],
		},
		{
			title = "Les portes closes",
			hint = [=[Aidez les Réprouvés à empêcher la malédiction de se répandre parmi les réfugiés du mur.]=],
			text = [=[Aujourd'hui, des réfugiés du nord se blottissent au pied du mur, malades et affamés. Ils espéraient trouver refuge en {link:gilneas}Gilneas{/link}. Les Gilnéens ont clairement fait savoir qu'ils ne laisseraient passer personne. Les {link:forsaken}Réprouvés{/link}, qui craignent la malédiction des worgens, y trouvent un réconfort. Ils disent qu'au moins la malédiction ne peut franchir les portes.]=],
		},
	},
	mentions = {
		{ text = "Enrayer la propagation" },
	},
	bonds = {
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "convoqua le conseil qu'il rejoignit" },
		{ id = "the-greymane-wall", name = "Le mur de Greymane", note = "son œuvre" },
	},
})
